import type CloudWebhook from '../lib/CloudWebhook';
import type { OAuth2CallbackCodeData, WebhooksMessageData } from '../manager/cloud';
export type OnOAuth2CallbackCodeEvent = {
    args: OAuth2CallbackCodeData;
    return: void;
};
export type OnWebhooksMessageEvent = {
    args: WebhooksMessageData;
    return: void;
};
export type GetHomeyIdEvent = {
    args: void;
    return: string;
};
export type GetLocalAddressEvent = {
    args: void;
    return: string;
};
export type RegisterWebhookEvent = {
    args: CloudWebhook;
    return: void;
};
export type UnregisterWebhookEvent = {
    args: CloudWebhook;
    return: void;
};
export type GenerateOAuth2CallbackEvent = {
    args: string;
    return: {
        token: string;
        url: string;
    };
};
export type HomeyCloudEvents = {
    onOAuth2CallbackCode: OnOAuth2CallbackCodeEvent;
    onWebhooksMessage: OnWebhooksMessageEvent;
};
export type SDKCloudEvents = {
    getHomeyId: GetHomeyIdEvent;
    getLocalAddress: GetLocalAddressEvent;
    registerWebhook: RegisterWebhookEvent;
    unregisterWebhook: UnregisterWebhookEvent;
    generateOAuth2Callback: GenerateOAuth2CallbackEvent;
};
